package io.rift.cronos;
import android.content.*;import android.database.Cursor;import android.database.sqlite.*;import org.json.*;
/** App-private checkpoint DB, excluded from personal backups. Global CAS epoch prevents stale resurrection. */
public final class DiscoveryIndexStore extends SQLiteOpenHelper implements DiscoveryIndex.Repository {
 public DiscoveryIndexStore(Context context){super(context,"rift-discovery-indices.sqlite",null,1);}
 @Override public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE epoch(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL)");db.execSQL("INSERT INTO epoch(id,revision) VALUES(1,0)");db.execSQL("CREATE TABLE indices(scope TEXT PRIMARY KEY,account TEXT NOT NULL,document TEXT NOT NULL)");}
 @Override public void onUpgrade(SQLiteDatabase db,int old,int next){throw new IllegalStateException("Unsupported discovery-index schema");}
 private static String account(String scope){String[] parts=scope.split("\\|",-1);if(parts.length!=3||!scope.equals(DiscoveryIndex.scope(parts[0].substring(3),parts[1],parts[2])))throw new IllegalArgumentException("Invalid index scope");return WorkspacePolicy.account(parts[0]);}
 private static long revision(SQLiteDatabase db){try(Cursor cursor=db.rawQuery("SELECT revision FROM epoch WHERE id=1",null)){if(!cursor.moveToFirst())throw new IllegalStateException("Index epoch missing");return cursor.getLong(0);}}
 @Override public DiscoveryIndex.Snapshot load(String scope)throws Exception{account(scope);SQLiteDatabase db=getReadableDatabase();db.beginTransaction();try{long version=revision(db);JSONObject state=null;try(Cursor c=db.rawQuery("SELECT document FROM indices WHERE scope=?",new String[]{scope})){if(c.moveToFirst())state=new JSONObject(JsonBudget.check(c.getString(0),131072,8));}db.setTransactionSuccessful();return new DiscoveryIndex.Snapshot(version,state);}finally{db.endTransaction();}}
 @Override public boolean commit(String scope,long expected,JSONObject state)throws Exception{String account=account(scope);if(expected<0||expected>=9007199254740991L)throw new IllegalArgumentException("Index revision bound");String document=state==null?null:JsonBudget.check(state.toString(),131072,8);SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{if(revision(db)!=expected)return false;if(state==null)db.delete("indices","scope=?",new String[]{scope});else{boolean exists;try(Cursor c=db.rawQuery("SELECT 1 FROM indices WHERE scope=?",new String[]{scope})){exists=c.moveToFirst();}if(!exists)try(Cursor c=db.rawQuery("SELECT COUNT(*) FROM indices",null)){c.moveToFirst();if(c.getInt(0)>=DiscoveryIndex.MAX_SCOPES)throw new IllegalStateException("16 discovery scopes maximum; delete an unused index first");}ContentValues row=new ContentValues();row.put("scope",scope);row.put("account",account);row.put("document",document);if(db.insertWithOnConflict("indices",null,row,SQLiteDatabase.CONFLICT_REPLACE)==-1)throw new IllegalStateException("Index checkpoint not saved");}db.execSQL("UPDATE epoch SET revision=? WHERE id=1",new Object[]{expected+1});db.setTransactionSuccessful();return true;}finally{db.endTransaction();}}
 public void clearAccount(String account){WorkspacePolicy.account(account);SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{long old=revision(db);if(old>=9007199254740991L)throw new IllegalStateException("Index revision bound");db.delete("indices","account=?",new String[]{account});db.execSQL("UPDATE epoch SET revision=? WHERE id=1",new Object[]{old+1});db.setTransactionSuccessful();}finally{db.endTransaction();}}
}
